using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;using Demo5.FrontEnd;
public static class RefineFacilityTags {
 public static string Run(){const string path="Assets/Prefabs/Settlement/SettlementScreen.prefab";var root=PrefabUtility.LoadPrefabContents(path);try{var c=root.GetComponent<SettlementController>();foreach(var f in root.GetComponentsInChildren<SettlementFacilityFocus>(true)){var parent=(RectTransform)f.transform;var r=(RectTransform)f.Caption.transform;r.anchoredPosition=new Vector2((parent.sizeDelta.x-154)/2,-parent.sizeDelta.y+18);r.sizeDelta=new Vector2(154,36);var t=f.Caption.GetComponentInChildren<Text>(true);t.text=t.text+" ›";t.fontSize=22;t.rectTransform.anchoredPosition=new Vector2(6,0);t.rectTransform.sizeDelta=new Vector2(142,36);f.Caption.GetComponent<Image>().raycastTarget=true;f.Caption.SetActive(true);}c.Main.transform.Find("FacilityHelp").GetComponent<Text>().text="시설 이름을 눌러 이용 · Alt: 위치 강조";PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}AssetDatabase.SaveAssets();EditorSceneManager.OpenScene("Assets/Scenes/Settlement.unity");return "Small persistent clickable facility tags; hover and Alt emphasize furniture.";}
}
